 "叶形标 = 保护区（按等级着色）；圆环 = 物种监测点（与保护区同址布设，按物种等级着色）": "葉形標 = 保護區（按等級著色）；圓環 = 物種監測點（與保護區同址布設，按物種等級著色）",
 "按名录「申报地区」归属到县区，圆点大小 = 项目数（仅统计能归到县区的项目）；点左侧清单里的项目可定位到该县区。": "按名錄「申報地區」歸屬到縣區，圓點大小 = 項目數（僅統計能歸到縣區的項目）；點左側清單裡的項目可定位到該縣區。",
 "清单为平台整理的山东饮食文化条目（鲁菜名菜 / 地方名吃 / 地理标志农产品 / 非遗美食），": "清單為平台整理的山東飲食文化條目（魯菜名菜 / 地方小吃 / 地理標誌農產品 / 非遺美食），",
 "游客整体评价较好，重点集中在景观体验、服务设施与交通便利性；高峰时段存在排队拥堵反馈。": "遊客整體評價較好，重點集中在景觀體驗、服務設施與交通便利性；高峰時段存在排隊壅塞回饋。",
 "范围内灾害风险指数 = 气象实况 + 近十年地震活动（两项为真实抓取数据）+ 地灾隐患 / 人流预警 / 水情监测（演示）": "範圍內災害風險指數 = 氣象實況 + 近十年地震活動（兩項為真實抓取數據）+ 地質災害隱患 / 人流預警 / 水情監測（示範）",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），未达到分级阈值（<3% 且 <2 条）": "範圍內（{scope}）近 {n} 條報導中，詞表判定為負面的 {negative} 條（{share}%），未達到分級閾值（<3% 且 <2 條）",
 "范围内（{scope}）近 {n} 条报道中，词表判定为负面的 {negative} 条（{share}%），达到中等级阈值（≥8% 或 ≥4 条）": "範圍內（{scope}）近 {n} 條報導中，詞表判定為負面的 {negative} 條（{share}%），達到中等級閾值（≥8% 或 ≥4 條）",
