 "济南三大名胜之首，趵突泉居七十二名泉之冠，三窟并发、四季恒温，素有「天下第一泉」之称。": "濟南三大名勝之首，趵突泉居七十二名泉之冠，三窟並發、四季恆溫，素有「天下第一泉」之稱。",
 "济南本地": "濟南本地",
 "五岳之首，世界文化与自然双遗产，主峰玉皇顶海拔 1545 米，历代帝王封禅告祭之地。": "五嶽之首，世界文化與自然雙遺產，主峰玉皇頂海拔 1545 公尺，歷代帝王封禪告祭之地。",
 "孔庙、孔府、孔林合称「三孔」，世界文化遗产，是儒家文化最完整的实物遗存。": "孔廟、孔府、孔林合稱「三孔」，世界文化遺產，是儒家文化最完整的實物遺存。",
 "山西": "山西",
 "黄河入海处的新生湿地，芦花飞雪、河海交汇，是东方白鹳、黑嘴鸥等珍禽的繁殖地。": "黃河入海處的新生濕地，蘆花飛雪、河海交匯，是東方白鸛、黑嘴鷗等珍禽的繁殖地。",
 "由济南众泉汇流而成的天然湖泊，「四面荷花三面柳，一城山色半城湖」即咏此处。": "由濟南眾泉匯流而成的天然湖泊，「四面荷花三面柳，一城山色半城湖」即詠此處。",
 "济南三大名胜之一，古称历山，隋代崖壁造像千余尊，登顶可俯瞰泉城全景。": "濟南三大名勝之一，古稱歷山，隋代崖壁造像千餘尊，登頂可俯瞰泉城全景。",
 "南四湖中面积最大的湖泊湿地，荷花芦苇连片，也是南水北调东线的重要调蓄湖泊。": "南四湖中面積最大的湖泊濕地，荷花蘆葦連片，也是南水北調東線的重要調蓄湖泊。",
 "《水浒传》故事发生地，梁山寨、忠义堂等遗迹尚存，是水浒文化旅游的核心景区。": "《水滸傳》故事發生地，梁山寨、忠義堂等遺跡尚存，是水滸文化旅遊的核心景區。",
 "有「旱码头」之称的周村大街，保存完好的明清商业街市，瑞蚨祥等老字号的发源地。": "有「旱碼頭」之稱的周村大街，保存完好的明清商業街市，瑞蚨祥等老字號的發源地。",
 "以《孙子兵法》为主题的仿古建筑群，位于兵圣孙武故里惠民县，是鲁北文旅地标。": "以《孫子兵法》為主題的仿古建築群，位於兵聖孫武故里惠民縣，是魯北文旅地標。",
