 "把子肉是济南传统名吃，用蒲草捆扎五花肉加酱油慢炖，肥而不腻、入口即化，是泉城人最日常的一口荤香。": "把子肉是濟南傳統名吃，用蒲草捆紮五花肉加醬油慢燉，肥而不膩、入口即化，是泉城人最日常的一口葷香。",
 "甜沫": "甜沫",
 "咸香微辣、糊香浓郁": "鹹香微辣、糊香濃郁",
 "甜沫配油条": "甜沫配油條",
 "甜沫配油旋": "甜沫配油旋",
 "名为甜沫实为咸粥，小米面熬底，加花生、粉条、豆腐皮与胡椒，是济南早餐的代表，与油旋、油条最相配。": "名為甜沫實為鹹粥，小米麵熬底，加花生、粉條、豆腐皮與胡椒，是濟南早餐的代表，與油旋、油條最相配。",
 "大葱蘸酱": "大蔥蘸醬",
 "葱烧海参": "蔥燒海參",
 "煎饼卷大葱": "煎餅捲大蔥",
 "章丘大葱以「高、长、脆、甜」著称，葱白可达半米以上，是鲁菜调味提鲜的核心食材，也是山东煎饼的灵魂搭配。": "章丘大蔥以「高、長、脆、甜」著稱，蔥白可達半公尺以上，是魯菜調味提鮮的核心食材，也是山東煎餅的靈魂搭配。",
 "原浆啤酒": "原漿啤酒",
 "啤酒配蛤蜊": "啤酒配蛤蜊",
 "啤酒炖海鲜": "啤酒燉海鮮",
 "青岛啤酒诞生于 1903 年，青岛啤酒博物馆与登州路啤酒街是城市夜生活的中心，「哈啤酒、吃蛤蜊」是青岛人的待客之道。": "青島啤酒誕生於 1903 年，青島啤酒博物館與登州路啤酒街是城市夜生活的中心，「哈啤酒、吃蛤蜊」是青島人的待客之道。",
 "崂山绿茶": "嶗山綠茶",
 "豆香清雅、汤色嫩绿": "豆香清雅、湯色嫩綠",
 "茶香虾仁": "茶香蝦仁",
 "崂山绿茶是「南茶北引」的成果，海雾与山泉滋养出叶片厚、耐冲泡的北方绿茶，豌豆香鲜明。": "嶗山綠茶是「南茶北引」的成果，海霧與山泉滋養出葉片厚、耐沖泡的北方綠茶，豌豆香鮮明。",
 "流亭猪蹄": "流亭豬蹄",
 "酱香透骨、胶质软糯": "醬香透骨、膠質軟糯",
 "猪蹄冻": "豬蹄凍",
 "流亭猪蹄源于城阳流亭，老汤酱制、焖煮入味，冷吃成冻切片，是青岛人逢年过节的硬菜。": "流亭豬蹄源於城陽流亭，老湯醬製、燜煮入味，冷吃成凍切片，是青島人逢年過節的硬菜。",
 "甜味烧饼": "甜味燒餅",
 "咸味烧饼": "鹹味燒餅",
 "周村烧饼以「薄如秋纸、酥似粉霜」闻名，手工贴炉烤制，全凭一双手控温，是国家级非物质文化遗产。": "周村燒餅以「薄如秋紙、酥似粉霜」聞名，手工貼爐烤製，全憑一雙手控溫，是國家級非物質文化遺產。",
 "博山豆腐箱": "博山豆腐箱",
 "咸鲜醇厚、味型复合": "鹹鮮醇厚、味型複合",
 "豆腐箱": "豆腐箱",
 "博山酥锅": "博山酥鍋",
 "博山烤肉": "博山烤肉",
 "博山豆腐箱是鲁中宴席名菜：豆腐切块炸制后挖空，填入三鲜肉馅再蒸，形似宝箱，是博山「三菜一汤」的核心。": "博山豆腐箱是魯中宴席名菜：豆腐切塊炸製後挖空，填入三鮮肉餡再蒸，形似寶箱，是博山「三菜一湯」的核心。",
 "小饼卷肉": "小餅捲肉",
 "小葱蘸酱": "小蔥蘸醬",
 "烤五花": "烤五花",
 "淄博烧烤以「小饼、小葱、小火炉」三件套出圈，自己动手卷饼把烧烤吃成了社交仪式，带动了城市的文旅热度。": "淄博燒烤以「小餅、小蔥、小火爐」三件套出圈，自己動手捲餅把燒烤吃成了社交儀式，帶動了城市的文旅熱度。",
 "菏泽单县羊肉汤": "菏澤單縣羊肉湯",
 "羊肉汤配烧饼": "羊肉湯配燒餅",
 "羊杂汤": "羊雜湯",
 "水煮羊肉": "水煮羊肉",
 "单县羊肉汤被称为「中华第一汤」，用本地青山羊慢火熬至汤白似奶，配死面烧饼食用，是鲁西南早餐的主角。": "單縣羊肉湯被稱為「中華第一湯」，用本地青山羊慢火熬至湯白似奶，配死麵燒餅食用，是魯西南早餐的主角。",
 "曹州牡丹宴": "曹州牡丹宴",
 "清雅花馔、咸甜并用": "清雅花饌、鹹甜並用",
 "牡丹花瓣羹": "牡丹花瓣羹",
 "牡丹虾仁": "牡丹蝦仁",
 "牡丹银丝酥": "牡丹銀絲酥",
 "菏泽古称曹州，牡丹园中的花馔以可食用牡丹入菜，把观赏名花做成宴席，是花都独有的时令风味。": "菏澤古稱曹州，牡丹園中的花饌以可食用牡丹入菜，把觀賞名花做成宴席，是花都獨有的時令風味。",
 "东营广饶肴驴肉": "東營廣饒肴驢肉",
 "咸香醇正、筋络弹韧": "鹹香醇正、筋絡彈韌",
 "肴驴肉": "肴驢肉",
 "驴肉拼盘": "驢肉拼盤",
 "广饶肴驴肉是省级非遗，老汤加十余味香料焖煮，色泽红润、咸香入味，是黄河口一带的传统熟食。": "廣饒肴驢肉是省級非遺，老湯加十餘味香料燜煮，色澤紅潤、鹹香入味，是黃河口一帶的傳統熟食。",
 "清蒸大闸蟹": "清蒸大閘蟹",
 "蟹粉豆腐": "蟹粉豆腐",
 "黄河入海口的弱碱水体养出青壳白肚、膏满黄肥的大闸蟹，与南方蟹相比更添一缕河海交汇的鲜甜。": "黃河入海口的弱鹼水體養出青殼白肚、膏滿黃肥的大閘蟹，與南方蟹相比更添一縷河海交匯的鮮甜。",
 "打卤面": "打滷麵",
 "温卤面": "溫滷麵",
 "炸酱面": "炸醬麵",
 "福山大面又称福山拉面，以「溜、抻、摔」成条，条型可细可宽，配以海味打卤，是胶东面食的代表。": "福山大麵又稱福山拉麵，以「溜、抻、摔」成條，條型可細可寬，配以海味打滷，是膠東麵食的代表。",
 "烟台苹果": "煙台蘋果",
 "脆甜多汁、香气突出": "脆甜多汁、香氣突出",
 "鲜食苹果": "鮮食蘋果",
 "苹果醋": "蘋果醋",
 "拔丝苹果": "拔絲蘋果",
 "烟台是中国现代苹果栽培的发源地，栖霞的丘陵沙壤与昼夜温差造就了脆甜化渣的果肉，是山东果业的金字招牌。": "煙台是中國現代蘋果栽培的發源地，棲霞的丘陵沙壤與晝夜溫差造就了脆甜化渣的果肉，是山東果業的金字招牌。",
 "蓬莱小面": "蓬萊小麵",
 "条细如丝、海味打卤": "條細如絲、海味打滷",
 "鱼卤小面": "魚滷小麵",
