 "蓬莱小面以真鲷熬汤打卤，面条细如发丝、入口滑爽，一碗面里能尝到黄海与渤海的交汇之鲜。": "蓬萊小麵以真鯛熬湯打滷，麵條細如髮絲、入口滑爽，一碗麵裡能嘗到黃海與渤海的交匯之鮮。",
 "肉火烧": "肉火燒",
 "素火烧": "素火燒",
 "配豆腐脑": "配豆腐腦",
 "潍坊肉火烧用土炉炭火烤制，皮薄酥脆、汁水饱满，与豆腐脑是本地最经典的早餐组合。": "濰坊肉火燒用土爐炭火烤製，皮薄酥脆、汁水飽滿，與豆腐腦是本地最經典的早餐組合。",
 "潍坊朝天锅": "濰坊朝天鍋",
