 "朝天锅卷饼": "朝天鍋捲餅",
 "热汤": "熱湯",
 "猪杂拼盘": "豬雜拼盤",
 "朝天锅源于清代集市，锅无盖朝天而得名，卤汤煮猪下货现切现卷，就着热汤与咸菜，是潍坊的市井名片。": "朝天鍋源於清代集市，鍋無蓋朝天而得名，滷湯煮豬下貨現切現捲，就著熱湯與鹹菜，是濰坊的市井名片。",
 "潍县萝卜": "濰縣蘿蔔",
 "脆甜微辣、汁水充盈": "脆甜微辣、汁水充盈",
 "生食萝卜": "生食蘿蔔",
 "萝卜丝拌海米": "蘿蔔絲拌海米",
 "「烟台苹果莱阳梨，不如潍县萝卜皮」，潍县萝卜皮薄肉绿、甜脆多汁，是山东人冬日的当家果蔬。": "「煙台蘋果萊陽梨，不如濰縣蘿蔔皮」，濰縣蘿蔔皮薄肉綠、甜脆多汁，是山東人冬日的當家果蔬。",
 "济宁甏肉干饭": "濟寧甏肉乾飯",
 "酱香软糯、油而不腻": "醬香軟糯、油而不膩",
 "甏肉干饭": "甏肉乾飯",
 "面筋丸子": "麵筋丸子",
 "油皮卷": "油皮捲",
 "甏肉干饭用陶甏炖肉，加入面筋、丸子和海带同煮，浇在米饭上，是运河码头上流传百年的市井快餐。": "甏肉乾飯用陶甏燉肉，加入麵筋、丸子和海帶同煮，澆在米飯上，是運河碼頭上流傳百年的市井快餐。",
 "曲阜熏豆腐": "曲阜燻豆腐",
 "熏香浓郁、外韧内嫩": "燻香濃郁、外韌內嫩",
 "熏豆腐炖白菜": "燻豆腐燉白菜",
 "熏豆腐炒辣椒": "燻豆腐炒辣椒",
 "熏豆腐以果木锯末熏制，色泽金黄、烟香入里，是孔府家常菜与地方集市小吃共同的常客。": "燻豆腐以果木鋸末燻製，色澤金黃、煙香入裡，是孔府家常菜與地方集市小吃共同的常客。",
 "泰山豆腐宴": "泰山豆腐宴",
 "清素鲜醇、荤素两宜": "清素鮮醇、葷素兩宜",
 "赤鳞鱼": "赤鱗魚",
 "白菜豆腐水": "白菜豆腐水",
 "泰山水与本地黄豆点出的豆腐细嫩无腥，泰山豆腐宴以百种豆制品成席，素菜荤做，是登泰山前的传统待客席面。": "泰山水與本地黃豆點出的豆腐細嫩無腥，泰山豆腐宴以百種豆製品成席，素菜葷做，是登泰山前的傳統待客席面。",
 "泰安煎饼": "泰安煎餅",
 "粗粮醇香、薄韧耐嚼": "粗糧醇香、薄韌耐嚼",
 "玉米煎饼": "玉米煎餅",
 "菜煎饼": "菜煎餅",
 "山东煎饼以泰安一带最讲工艺，石磨糊子、鏊子摊薄，卷大葱蘸酱，是齐鲁大地最有辨识度的日常主食。": "山東煎餅以泰安一帶最講工藝，石磨糊子、鏊子攤薄，捲大蔥蘸醬，是齊魯大地最有辨識度的日常主食。",
 "鲅鱼水饺": "鮁魚水餃",
 "鲅鱼丸子": "鮁魚丸子",
 "鲅鱼水饺是胶东渔家待客的头道主食，鱼肉加五花肉与韭菜搅打成馅，皮薄馅大、一口爆汁。": "鮁魚水餃是膠東漁家待客的頭道主食，魚肉加五花肉與韭菜攪打成餡，皮薄餡大、一口爆汁。",
 "荣成海带": "榮成海帶",
 "厚韧脆嫩、海味清鲜": "厚韌脆嫩、海味清鮮",
 "海带炖排骨": "海帶燉排骨",
 "凉拌海带丝": "涼拌海帶絲",
 "荣成是中国海带之乡，冷流水海域养出的海带叶片宽厚，是中国海藻产业的核心产区。": "榮成是中國海帶之鄉，冷流水海域養出的海帶葉片寬厚，是中國海藻產業的核心產區。",
 "日照绿茶": "日照綠茶",
 "栗香高扬、耐泡浓醇": "栗香高揚、耐泡濃醇",
 "茶香熏鱼": "茶香燻魚",
 "日照绿茶与崂山绿茶同为「南茶北引」的成果，生长周期长、内含物高，栗香与豌豆香明显。": "日照綠茶與嶗山綠茶同為「南茶北引」的成果，生長週期長、內含物高，栗香與豌豆香明顯。",
 "临沂糁汤": "臨沂糝湯",
 "胡椒辛香、汤稠味厚": "胡椒辛香、湯稠味厚",
 "牛肉糁": "牛肉糝",
 "鸡肉糁": "雞肉糝",
 "配油条": "配油條",
 "糁（sá）汤用牛骨或老母鸡熬汤，加麦仁与胡椒冲鸡蛋，是临沂人天亮就排队的一碗热汤。": "糝（sá）湯用牛骨或老母雞熬湯，加麥仁與胡椒沖雞蛋，是臨沂人天亮就排隊的一碗熱湯。",
 "沂蒙煎饼": "沂蒙煎餅",
 "杂粮焦香、薄如纸页": "雜糧焦香、薄如紙頁",
 "小米煎饼": "小米煎餅",
 "煎饼卷咸菜": "煎餅捲鹹菜",
 "煎饼卷炒鸡": "煎餅捲炒雞",
 "沂蒙煎饼以小米、玉米、高粱混合摊制，旧时是山区耐存的干粮，如今卷一切成为沂蒙味道的载体。": "沂蒙煎餅以小米、玉米、高粱混合攤製，舊時是山區耐存的乾糧，如今捲一切成為沂蒙味道的載體。",
 "扒鸡拌面": "扒雞拌麵",
 "德州扒鸡与符离集烧鸡、道口烧鸡并称中国三大名鸡，大锅焖煮至「热中一抖骨肉分」，是运河码头的百年手艺。": "德州扒雞與符離集燒雞、道口燒雞並稱中國三大名雞，大鍋燜煮至「熱中一抖骨肉分」，是運河碼頭的百年手藝。",
 "乐陵金丝小枣": "樂陵金絲小棗",
 "肉厚核小、甜糯拉丝": "肉厚核小、甜糯拉絲",
 "干枣": "乾棗",
 "枣糕": "棗糕",
 "枣夹核桃": "棗夾核桃",
 "乐陵金丝小枣掰开可见缕缕金丝，含糖量高、皮薄肉厚，是鲁北沙地千年枣林的结晶。": "樂陵金絲小棗掰開可見縷縷金絲，含糖量高、皮薄肉厚，是魯北沙地千年棗林的結晶。",
 "聊城魏氏熏鸡": "聊城魏氏燻雞",
 "熏香入骨、韧而不柴": "燻香入骨、韌而不柴",
 "熏鸡": "燻雞",
 "熏鸡丝拌黄瓜": "燻雞絲拌黃瓜",
 "魏氏熏鸡用老汤焖煮后再以锯末熏制，皮色栗红、香透筋骨，是聊城东昌府的老字号名产。": "魏氏燻雞用老湯燜煮後再以鋸末燻製，皮色栗紅、香透筋骨，是聊城東昌府的老字號名產。",
 "高唐老豆腐": "高唐老豆腐",
 "嫩滑爽口、卤香微辣": "嫩滑爽口、滷香微辣",
